<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\Accessor\TenantConfigAllowPasswordGrantAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantConfigAllowPasswordGrantAccessor trait.
 *
 * Covers null default, string/VO assignment via withAllowPasswordGrant,
 * getAllowPasswordGrant/allowPasswordGrant accessors, and isAllowPasswordGrantChanged with/without original.
 */
class TenantConfigAllowPasswordGrantAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withAllowPasswordGrant creates a new instance with the AllowPasswordGrant set
     * from a string value, and getAllowPasswordGrant returns the primitive string.
     */
    public function testWithAllowPasswordGrantFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigAllowPasswordGrantAccessorUnitTest();

        // Act
        $result = $holder->withAllowPasswordGrant(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->isAllowPasswordGrant());
    }
    /**
     * Asserts that withallowPasswordGrant has access to the value object
     * from a string value, and getAllowPasswordGrant returns the primitive string.
     */
    public function testWithAllowPasswordGrantFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigAllowPasswordGrantAccessorUnitTest();

        // Act
        $result = $holder->withAllowPasswordGrant(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->allowPasswordGrant()->value());
    }
    public function testChangedAllowPasswordGrant(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigAllowPasswordGrantAccessorUnitTest()->withAllowPasswordGrant(true);
        $original = $holder->withAllowPasswordGrant(true);
        $same = $holder->withAllowPasswordGrant(true);
        $modified = $holder->withAllowPasswordGrant(false);

        // Act
        $withSame = $original->isAllowPasswordGrantChanged($same);
        $withDiferent = $original->isAllowPasswordGrantChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantConfigAllowPasswordGrantAccessorUnitTest
{
    use TenantConfigAllowPasswordGrantAccessor;
}
